<template><AsyncState :loading="loading" :error="error" :empty="!config?.hasConfig"><template #empty><p>{{t('project.no_config')}}</p></template><main class="page"><PageHeader :title="t('project.config')"/><SectionCard :title="t('project.dir')"><CopyableValue :value="config.dir"/></SectionCard><SectionCard :title="t('project.tools')"><div v-for="(v,n) in config.tools" :key="n" class="row"><b>{{n}}</b><span>{{v}}</span><ConfirmAction :title="t('project.tool_unset')" @confirm="$emit('unset-tool',n)"><template #trigger><button data-action="unset-project-tool">{{t('btn.remove')}}</button></template></ConfirmAction></div><form class="row" @submit.prevent="add"><input v-model.trim="tool" data-field="project-tool" :aria-label="t('project.tool_placeholder')"/><input v-model.trim="version" data-field="project-version" :aria-label="t('project.version_placeholder')"/><button data-action="set-project-tool" :disabled="!tool||!version">{{t('btn.add')}}</button></form></SectionCard><SectionCard :title="t('project.env_vars')"><div v-for="(v,n) in config.env" :key="n" class="row"><b>{{n}}</b><span>{{v}}</span></div></SectionCard><SectionCard :title="t('project.tasks')"><div v-for="(task,n) in config.tasks" :key="n" class="row"><b>{{n}}</b><CopyableValue :value="task.run"/><StatusBadge v-if="taskStates[n]" live :tone="taskStates[n]==='success'?'success':taskStates[n]==='error'?'error':'info'">{{t(`tasks.status_${taskStates[n]==='error'?'failed':taskStates[n]}`)}}</StatusBadge><button data-action="run-project-task" :disabled="taskStates[n]==='running'" @click="$emit('run-task',n)">{{t('btn.run')}}</button></div></SectionCard><SectionCard :title="t('lockfile.title')"><template #actions><button data-action="refresh-lockfile" :disabled="lockfileLoading" @click="$emit('refresh-lockfile')">{{t('btn.refresh')}}</button><button v-if="lockfile?.found" data-action="install-lockfile" :disabled="lockfileInstalling" @click="$emit('install-lockfile')">{{t('lockfile.install_all')}}</button></template><template v-if="lockfile?.found"><CopyableValue :value="lockfile.dir"/><div v-for="(item,n) in lockfile.tools" :key="n" class="row"><b>{{n}}</b><span>{{item.resolved}}</span><CopyableValue v-if="item.sha256" :value="item.sha256"/></div></template><p v-else>{{t('lockfile.empty')}}</p></SectionCard></main></AsyncState></template>
<script setup>import{ref}from'vue';import AsyncState from'../components/AsyncState.vue';import ConfirmAction from'../components/ConfirmAction.vue';import CopyableValue from'../components/CopyableValue.vue';import PageHeader from'../components/PageHeader.vue';import SectionCard from'../components/SectionCard.vue';import StatusBadge from'../components/StatusBadge.vue';defineProps({config:{type:Object,default:null},lockfile:{type:Object,default:null},taskStates:{type:Object,default:()=>({})},loading:Boolean,error:{type:[String,Error],default:null},lockfileLoading:Boolean,lockfileInstalling:Boolean,t:{type:Function,required:true}});const emit=defineEmits(['set-tool','unset-tool','run-task','refresh-lockfile','install-lockfile']);const tool=ref(''),version=ref('');function add(){if(!tool.value||!version.value)return;emit('set-tool',tool.value,version.value);tool.value='';version.value=''}</script>
<style scoped>.page{display:grid;gap:16px;min-width:0}.row{display:flex;align-items:center;gap:10px;min-width:0;margin:8px 0;flex-wrap:wrap}.row :deep(.copyable-value){min-width:0}input{min-width:0;padding:8px}@media(max-width:640px){.row{align-items:stretch;flex-direction:column}.row button{width:100%}}</style>
